import {attacksFor,ATTACKS,CONSUMABLES,skillName,ruleFor,totalDamage,shopQuote} from './economy.js';
import {PERSONA_INFO} from './personas.js';
export function createRespawnShop({onPurchase,onPersonaChange,onRespawn,now=Date.now}){
 const root=document.createElement('section');root.className='respawn-shop';root.setAttribute('aria-label','Respawn shop');let current,signature='',timer;
 const header=document.createElement('header'),title=document.createElement('h2'),balance=document.createElement('strong'),countdown=document.createElement('p'),characters=document.createElement('div'),skills=document.createElement('div'),items=document.createElement('div'),respawn=document.createElement('button');
 title.textContent='Next life';header.append(title,balance);characters.className='shop-characters';skills.className='shop-skills';items.className='shop-items';respawn.className='respawn-go';respawn.onclick=()=>{respawn.disabled=true;onRespawn();};const streakTip=document.createElement('small');streakTip.className='shop-streak-tip';streakTip.textContent='Every 5 people you kill in a row, you get an Orbital Strike Cannon.';root.append(header,countdown,characters,skills,items,respawn,streakTip);
 const tick=()=>{if(!current)return;const seconds=Math.max(0,Math.ceil((current.respawnAt-now())/1000));countdown.textContent=seconds?`Respawn ready in ${seconds}s · shop while you wait`:'Ready to respawn · purchases stay with you';respawn.textContent=seconds?`Respawn in ${seconds}s`:'Respawn';respawn.disabled=seconds>0;};
 function update(player){current=player;tick();if(!timer)timer=setInterval(tick,100);const persona=player.nextPersona||player.persona||'mage',next=JSON.stringify([persona,player.loadout,player.score?.coins]);if(signature===next)return;signature=next;balance.innerHTML='<img class="coin-icon" src="/media/coin.svg" alt="Coins"> ';balance.append(String(player.score?.coins||0));
  characters.replaceChildren(...Object.entries(PERSONA_INFO).map(([id,info])=>{const b=document.createElement('button');b.textContent=info.symbol+' '+info.name;b.setAttribute('aria-pressed',String(id===persona));b.onclick=()=>onPersonaChange(id);return b;}));
  const preview={...player,persona};skills.replaceChildren(...attacksFor(persona).map(id=>{const card=document.createElement('article'),name=document.createElement('h3'),stats=document.createElement('p'),level=player.loadout.skills[id]||0,rule=ruleFor(preview,id);card.className='shop-skill'+(level>1?' upgraded':'');name.textContent=ATTACKS[id].icon+' '+skillName(preview,id);stats.textContent=`♥ ${totalDamage(rule)/10}  ·  ◆ ${rule.manaCost}  ·  ◷ ${Number((rule.cooldown/1000).toFixed(2))}s`;stats.setAttribute('aria-label',`${totalDamage(rule)/10} hearts damage, ${rule.manaCost} mana, ${Number((rule.cooldown/1000).toFixed(2))} second delay`);card.append(name,stats);if(ATTACKS[id].upgradeMultiHit){const area=document.createElement('small');area.className='shop-area-note';area.textContent=(level>1?'':'Upgrade: ')+'Hits up to 3 players within 5m. Nearby players take half damage.';card.append(area);}
   if(!level){const quote=shopQuote(player.loadout,persona,'unlock',id),buy=document.createElement('button');buy.textContent=quote.error?'Unlock the previous skill':`Unlock · ${quote.cost} coins`;buy.disabled=!!quote.error||(player.score?.coins||0)<quote.cost;buy.onclick=()=>onPurchase('unlock',id);card.append(buy);}else if(level===1){const quote=shopQuote(player.loadout,persona,'upgrade',id);if((player.score?.coins||0)>=quote.cost){const b=document.createElement('button');b.className='shop-upgrade';b.textContent=`↑ Upgrade · ${quote.cost}`;b.setAttribute('aria-label',`Upgrade ${ATTACKS[id].name} to ${ATTACKS[id].upgrade} for ${quote.cost} coins`);b.onclick=()=>onPurchase('upgrade',id);card.append(b);}else{const note=document.createElement('small');note.textContent=`Upgrade to ${ATTACKS[id].upgrade} · ${quote.cost} coins`;card.append(note);}}else{const note=document.createElement('small');note.textContent='Upgraded · more damage, same delay';card.append(note);}return card;}));
  items.replaceChildren(...Object.entries(CONSUMABLES).map(([id,item])=>{const row=document.createElement('div'),label=document.createElement('span'),buy=document.createElement('button');label.textContent=`${player.loadout.consumables[id]||0}× ${item.name}${id==='shield'?` · ${item.duration/1000}s`:id==='heal'?' · 5 ♥':' · 3s / 10m'}`;const quote=shopQuote(player.loadout,persona,'consumable',id);buy.textContent=quote.error?'Full':`Buy · ${item.cost}`;buy.setAttribute('aria-label',quote.error?`${item.name} inventory full`:`Buy ${item.name} for ${item.cost} coins`);buy.disabled=!!quote.error||(player.score?.coins||0)<item.cost;buy.onclick=()=>onPurchase('consumable',id);row.append(label,buy);return row;}));
 }
 return{root,update,stop(){clearInterval(timer);timer=null;current=null;}};
}
